// This file is not generated by Speakeasy — it lets flags that hold prose accept
// prose.
//
// The problem it solves: a field marked `nullable: true` in the OpenAPI spec is
// generated as FlagKindJSON, because JSON is the only encoding that can express
// a real null distinctly from the four-letter string "null". That is correct,
// and it is why --instructions null clears the field instead of setting it to
// the word. But it also means the obvious invocation fails:
//
//	vf agent update --instructions 'You are a support agent for Acme.'
//	  invalid value for --instructions: error unmarshalling json response body:
//	  invalid character 'Y' looking for beginning of value
//
// The field's own description says "Markdown text", and the error names the
// first letter of the sentence. Nothing tells the reader the value must be
// wrapped in JSON quotes. The workaround — '"You are a support agent."' — is
// quotes inside quotes, which is exactly the thing shell users and coding agents
// get wrong.
//
// So: when a JSON flag fails to parse AND its destination ultimately holds a Go
// string, re-encode the raw text as a JSON string and use that. Nullability is
// preserved because the null branch runs earlier, in buildJSONField.
//
// The precedent is in buildJSONField already: reflect.Interface destinations
// have done exactly this ("Not valid JSON — treat as raw string") since before
// this file existed. This extends an established behavior to the string case
// rather than inventing one.
//
// The trade being made, stated plainly: for these flags, malformed JSON that
// used to fail now succeeds as literal text. That is right for someone writing
// markdown — the overwhelmingly common case for these fields — and wrong for
// someone who meant to pass JSON and typo'd it. Fields that hold structs, maps
// or slices are deliberately excluded, so a mistyped JSON object still fails
// loudly everywhere it would be meaningless as text.

package flagutil

import (
	"encoding/json"
	"fmt"
	"reflect"

	"github.com/voiceflow/cli/internal/sdk/sdkinternal/utils"
)

// stringLikeJSONTarget reports whether a FlagKindJSON destination ultimately
// holds a Go string, unwrapping pointers and OptionalNullable[T].
//
// The OptionalNullable clause is the load-bearing part. OptionalNullable[T] is
// defined as map[bool]*T, so its reflect.Kind is Map — indistinguishable by kind
// alone from map[string]any. Requiring a bool key admits OptionalNullable[string]
// and rejects every ordinary map. Checking Kind() == String alone would match
// nothing at all, since no FlagKindJSON flag targets a bare string.
func stringLikeJSONTarget(t reflect.Type) bool {
	for t.Kind() == reflect.Ptr {
		t = t.Elem()
	}
	// OptionalNullable[T] == map[bool]*T
	if t.Kind() == reflect.Map && t.Key().Kind() == reflect.Bool && t.Elem().Kind() == reflect.Ptr {
		t = t.Elem().Elem()
		for t.Kind() == reflect.Ptr {
			t = t.Elem()
		}
	}
	return t.Kind() == reflect.String
}

// setJSONFieldAsRawText is the recovery path for a JSON flag whose value did not
// parse. For string-valued destinations it retries with the input quoted as a
// JSON string; for everything else it converts the parse failure into a
// FlagValueError that explains what the flag actually wanted.
//
// The retry always builds a fresh destination rather than reusing the one the
// failed attempt wrote into: a partial unmarshal may already have mutated it,
// and silently shipping a half-populated value would be worse than the error
// this replaces.
func setJSONFieldAsRawText(field reflect.Value, fieldType reflect.Type, isPtr bool, val string, m FlagMeta, cause error) error {
	if !stringLikeJSONTarget(field.Type()) {
		return &FlagValueError{
			Flag:     m.FlagName,
			Value:    val,
			Expected: "expected a JSON value",
			Hints: []string{
				`objects and arrays must be valid JSON, e.g. --` + m.FlagName + ` '{"key":"value"}'`,
				"pass null to clear the field: --" + m.FlagName + " null",
			},
			Cause: cause,
		}
	}

	// json.Marshal of a string cannot fail, but handle it rather than ignore it.
	quoted, err := json.Marshal(val)
	if err != nil {
		return &FlagValueError{
			Flag:     m.FlagName,
			Value:    val,
			Expected: "expected text or a JSON string",
			Cause:    cause,
		}
	}

	if isPtr {
		holder := reflect.New(reflect.PtrTo(fieldType))
		holder.Elem().Set(reflect.New(fieldType))
		if err := utils.UnmarshalJsonFromString(string(quoted), holder.Interface(), m.Annotations); err != nil {
			return rawTextRetryFailed(m, val, cause)
		}
		field.Set(holder.Elem())
		return nil
	}

	target := reflect.New(fieldType)
	if err := utils.UnmarshalJsonFromString(string(quoted), target.Interface(), m.Annotations); err != nil {
		return rawTextRetryFailed(m, val, cause)
	}
	field.Set(target.Elem())
	return nil
}

// rawTextRetryFailed reports a destination that looked string-shaped but refused
// a JSON string anyway. Reaching this means stringLikeJSONTarget and the SDK's
// unmarshaler disagree, so it names that explicitly instead of blaming the input.
func rawTextRetryFailed(m FlagMeta, val string, cause error) error {
	return &FlagValueError{
		Flag:     m.FlagName,
		Value:    val,
		Expected: fmt.Sprintf("could not be set from text (%v)", cause),
		Hints:    []string{"this is a bug in the CLI — please report it with the command you ran"},
		Cause:    cause,
	}
}
